    public static string Classify(string? name, string? mimeType = null)
    {
        // File names, not the containing directory, determine the extension. No filesystem access.
        var leaf = (name ?? "").Replace('\\', '/').Split('/')[^1];
        var dot = leaf.LastIndexOf('.');
        if (dot >= 0 && Extensions.TryGetValue(leaf[(dot + 1)..].ToLowerInvariant(), out var type)) return type;
        var mime = (mimeType ?? "").Split(';')[0].Trim().ToLowerInvariant();
        if (MimeTypes.TryGetValue(mime, out type)) return type;
        if (mime.StartsWith("image/", StringComparison.Ordinal)) return "file-image";
        if (mime.StartsWith("audio/", StringComparison.Ordinal)) return "file-audio";
        if (mime.StartsWith("video/", StringComparison.Ordinal)) return "file-video";
        if (mime.StartsWith("font/", StringComparison.Ordinal)) return "file-font";
        if (mime.StartsWith("model/", StringComparison.Ordinal)) return "file-3d";
        if (mime.StartsWith("text/", StringComparison.Ordinal)) return "file-text";
        return "file";
    }
